{
  "description": "The creature is depicted in right-facing profile standing bipedally on two hind legs against a plain light background. It has the overall body shape, fur, head and tail of a red fox combined with the large folded wings and plumage pattern of a barn owl. The head, neck, chest, hindquarters, legs and long bushy tail are fox-like with reddish-orange and white fur, while two broad feathered wings are attached to the sides of the torso in place of forelegs. The fur on the chest and throat is long and pale cream with fine dark speckling, and the wings show mottled tan, cream, grey and brown with dark spots and barring. The posture is alert and upright, with the tail trailing behind and the wings held folded against the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like head at the front top of the body with a pointed snout, reddish-orange fur on the forehead, cheeks and sides, white fur on the muzzle, chin and throat, a small black nose at the tip, brown eyes with dark pupils, and fine whiskers on the muzzle",
      "where": "at the anterior end of the neck, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two large upright triangular pointed ears with reddish-orange outer fur, blackish tips and edges, and pale cream and dark grey inner fur",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "two muscular digitigrade hind legs covered in reddish-brown fur with cream-white on the inner thighs and lower chest, bent at the hock and stifle joints",
      "where": "beneath the mid and rear torso, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "two fox-like paws with dark brown fur, rounded toe pads and short dark claws",
      "where": "at the distal ends of the hind legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long thick bushy tail covered in dense reddish-brown fur that fades to white at the tip, with long guard hairs",
      "where": "extending from the rear of the hindquarters, trailing low behind the body to the left"
    },
    {
      "part": "wings",
      "looks_like": "two large folded bird wings with broad rounded tips and layered flight feathers, one fully visible on the near side and the second partially visible behind the chest on the far side",
      "where": "attached to the sides of the torso at shoulder level, covering the lateral body wall"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers in barn owl pattern: tan and cream coverts mottled with grey and small black spots, and long cream flight feathers with dark brown-black bars and spots along the edges",
      "where": "covering the entire surface of both wings from the shoulder to the wingtip"
    },
    {
      "part": "markings",
      "looks_like": "small scattered dark brown-black spots on the pale cream fur of the neck, throat and upper chest and on the wing coverts, plus larger grey-brown mottled patches and barring on the upper wing and flight feathers",
      "where": "on the ventral neck and chest and across the dorsal and lateral surfaces of the wings"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "barn owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
